  explicacion: `En pacientes seleccionados con riesgo muy alto, especialmente con fracturas vertebrales múltiples o recientes, puede considerarse tratamiento anabólico como teriparatida, abaloparatida o romosozumab, de acuerdo con indicaciones, disponibilidad y contraindicaciones. Al finalizar el curso anabólico suele requerirse un antiresortivo para mantener el beneficio sobre la densidad ósea.`,
